import { Badge } from '@/components/ui/badge'

type TodayMenuProps = {
    menu: {
        id: string
        name: string
        description: string | null
        type: string
        plates: {
            id: string
            name: string
            price: number
            description: string
            image: string | null
            categoryPlate: {
                id: string
                name: string
            } | null
        }[]
        categoryPlates: {
            id: string
            name: string
        }[]
    } | null
}

export default function TodayMenuSection({ menu }: TodayMenuProps) {
    if (!menu) {
        return null
    }

    return (
        <section className="py-20 md:py-28 bg-linear-to-b from-background to-muted/30">
            <div className="mx-auto max-w-7xl px-4 sm:px-6">
                {/* Section Header */}
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    whileInView={{ opacity: 1, y: 0 }}
                    viewport={{ once: true }}
                    transition={{ duration: 0.6 }}
                    className="text-center mb-12 md:mb-16"
                >
                    <Badge className="mb-4 gap-1.5 px-4 py-1.5 bg-linear-to-r from-primary to-primary/80 text-primary-foreground">
                        <Clock className="h-3.5 w-3.5" />
