                        viewport={{ once: true }}
                        transition={{ duration: 0.6, delay: 0.1 }}
                        className="flex flex-wrap justify-center gap-3 mb-10"
                    >
                        {menu.categoryPlates.map((cat) => (
                            <Badge
                                key={cat.id}
                                variant="secondary"
                                className="px-4 py-2 text-sm font-medium"
                            >
                                {cat.name}
                            </Badge>
                        ))}
                    </motion.div>
                )}

                {/* Plates Grid */}
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 md:gap-8">
                    {menu.plates.slice(0, 6).map((plate, index) => (
                        <motion.div
                            key={plate.id}
                            initial={{ opacity: 0, y: 30 }}
                            whileInView={{ opacity: 1, y: 0 }}
                            viewport={{ once: true }}
                            transition={{ duration: 0.5, delay: index * 0.1 }}
                        >
                            <Card className="group overflow-hidden border-0 shadow-lg hover:shadow-2xl transition-all duration-500 bg-card h-full">
                                <CardContent className="p-0">
                                    {/* Image */}
                                    <div className="relative h-48 overflow-hidden">
                                        {plate.image ? (
                                            <Image
                                                src={plate.image}
                                                alt={plate.name}
                                                fill
                                                className="object-cover transition-transform duration-700 group-hover:scale-110"
                                            />
                                        ) : (
                                            <div className="w-full h-full flex items-center justify-center bg-muted">
                                                <UtensilsCrossed className="h-12 w-12 text-muted-foreground/30" />
                                            </div>
                                        )}
                                        {/* Price Tag */}
                                        <div className="absolute top-4 right-4">
                                            <Badge className="bg-primary text-primary-foreground font-bold text-base px-3 py-1 shadow-lg">
                                                {plate.price.toFixed(2)}€
                                            </Badge>
                                        </div>
                                        {/* Category */}
                                        {plate.categoryPlate && (
                                            <div className="absolute bottom-4 left-4">
                                                <Badge variant="secondary" className="backdrop-blur-sm bg-background/80">
                                                    {plate.categoryPlate.name}
                                                </Badge>
                                            </div>
                                        )}
                                    </div>

                                    {/* Content */}
                                    <div className="p-5">
                                        <h3 className="font-semibold text-lg mb-2 group-hover:text-primary transition-colors">
                                            {plate.name}
                                        </h3>
                                        <p className="text-sm text-muted-foreground line-clamp-2">
                                            {plate.description}
                                        </p>
                                    </div>
                                </CardContent>
                            </Card>
                        </motion.div>
                    ))}
                </div>

                {/* CTA */}
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    whileInView={{ opacity: 1, y: 0 }}
                    viewport={{ once: true }}
                    transition={{ duration: 0.6, delay: 0.4 }}
                    className="text-center mt-12"
                >
                    <Link href="/menu">
                        <Button size="lg" className="gap-2 group">
                            Voir le Menu Complet
                            <ArrowRight className="h-4 w-4 transition-transform group-hover:translate-x-1" />
                        </Button>
                    </Link>
                </motion.div>
            </div>
        </section>
    )
}

'use server';

import { loginSchema, signupSchema } from '@/lib/validators/auth';
import { z } from 'zod';
import { auth } from '@/lib/auth';

type SignUpResult = { success: true } | { success: false; error: string };
type SignInResult = { success: true } | { error: string };

/* ----------------------------------
   SIGN UP (unchanged)
----------------------------------- */
export async function signUpAction(
  values: z.infer<typeof signupSchema>
): Promise<SignUpResult> {
  const parsed = signupSchema.safeParse(values);

  if (!parsed.success) {
    return { success: false, error: 'Données invalides' };
  }

  try {
    await auth.api.signUpEmail({
      body: {
        email: parsed.data.email,
        password: parsed.data.password,
        name: parsed.data.name,
      },
    });

    return { success: true };
  } catch (error: any) {
    return {
      success: false,
      error: error?.message ?? 'Impossible de créer le compte',
    };
  }
}

/* ----------------------------------
   FIXED SIGN IN (same logic)
----------------------------------- */

export type LoginInput = z.infer<typeof loginSchema>;
export async function signInAction(values: LoginInput): Promise<SignInResult> {
  const parsed = loginSchema.safeParse(values);

  if (!parsed.success) {
    return { error: 'Invalid form data' };
  }

  try {
    await auth.api.signInEmail({
      body: {
        email: parsed.data.email,
        password: parsed.data.password,
      },
    });

    return { success: true };
  } catch (error: any) {
    return {
      error: error?.message ?? 'Invalid email or password',
    };
  }
}

'use server';

import prisma from '@/lib/prisma';
import { menuSchema } from '@/lib/validators/menu';
import { revalidatePath, revalidateTag } from 'next/cache';
import { randomUUID } from 'crypto';

type ActionResult = { success: true } | { success: false; error: string };

export async function updateMenuAction(menuId: string, data: any) {
  try {
    await prisma.menu.update({
      where: { id: menuId },
      data: {
        name: data.name,
        description: data.description,
        isFeatured: data.isFeatured,
        startTime: data.startTime ? new Date(data.startTime) : null,
        endTime: data.endTime ? new Date(data.endTime) : null,
        plates: {
          set: data.plates.map((id: string) => ({ id })),
        },
        categoryPlates: {
          set: data.categories.map((id: string) => ({ id })),
        },
      },
    });

    revalidatePath('/admin/menus');
    revalidateTag('menus', 'max');
    revalidateTag('menu-data', 'max');
    return { success: true };
  } catch (error) {
    return { success: false, error: 'Failed to update menu' };
  }
}

export async function deleteMenuAction(id: string) {
  await prisma.menu.delete({
    where: { id },
  });

  revalidatePath('/admin/menus');
  revalidateTag('menus', 'max');
  revalidateTag('menu-data', 'max');
}

export async function toggleFeaturedMenu(id: string, value: boolean) {
  await prisma.menu.update({
    where: { id },
    data: {
      isFeatured: value,
      updatedAt: new Date(),
    },
  });

  revalidatePath('/admin/menus');
  revalidateTag('menus', 'max');
  revalidateTag('menu-data', 'max');
}

export async function toggleActiveMenu(id: string, value: boolean) {
  await prisma.menu.update({
    where: { id },
    data: {
      isActive: value,
      updatedAt: new Date(),
    },
  });

  revalidatePath('/admin/menus');
  revalidateTag('menus', 'max');
  revalidateTag('menu-data', 'max');
}

export async function getMenus() {
  return await prisma.menu.findMany({
    orderBy: { createdAt: 'desc' },
    include: {
      plates: {
        include: {
          categoryPlate: true,
        },
      },
      categoryPlates: true, // if menu ↔ categories exists
    },
  });
}

export async function createMenuAction(values: unknown): Promise<ActionResult> {
  try {
    const parsed = menuSchema.safeParse(values);

    if (!parsed.success) {
      return { success: false, error: 'Invalid menu data' };
    }

    const {
      name,
      description,
      isFeatured,
      startTime,
      endTime,
      plates,
      categories,
    } = parsed.data;

    await prisma.menu.create({
      data: {
        name,
        slug: name.toLowerCase().replace(/\s+/g, '-'),
        description,
        isFeatured,
        startTime: startTime ? new Date(startTime) : null,
        endTime: endTime ? new Date(endTime) : null,

        plates: {
          connect: (plates ?? []).map((id) => ({ id })),
        },

        categoryPlates: {
          connect: (categories ?? []).map((id) => ({ id })),
        },
      },
    });

    revalidatePath('/admin/menus');
    revalidateTag('menus', 'max');
    revalidateTag('menu-data', 'max');
    return { success: true };
  } catch (error) {
    console.error(error);
    return { success: false, error: 'Failed to create menu' };
  }
}

